package com.waldron.adventurerspack;
import net.minecraft.gametest.framework.*;
import net.minecraftforge.gametest.*;
import net.minecraft.world.item.*;
import net.minecraft.world.item.enchantment.*;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.entity.projectile.AbstractArrow;
@GameTestHolder(AdventurersPack.ID)
@PrefixGameTestTemplate(false)
public class RequiemTests {
 @GameTest(template="empty") public static void allFormsPreserveData(GameTestHelper h){var source=new ItemStack(AdventurersPack.REQUIEM.get());source.setDamageValue(555);source.enchant(Enchantments.UNBREAKING,3);source.setHoverName(net.minecraft.network.chat.Component.literal("My Requiem"));source.getOrCreateTag().putUUID("AdventurersPackLease",java.util.UUID.randomUUID());var current=source;for(int i=1;i<Requiem.NAMES.length;i++){current=Requiem.transformed(current,i);h.assertTrue(current.getTag().equals(source.getTag())&&current.getMaxDamage()==4096,"All forms preserve complete item data and durability");}h.assertTrue(ItemStack.matches(source,Requiem.transformed(current,0)),"Round trip has no loss");h.assertTrue(Requiem.transformed(source,10).isEmpty(),"Invalid form rejected");h.succeed();}
 @GameTest(template="empty") public static void validatesHeldItem(GameTestHelper h){var p=h.makeMockPlayer();p.getInventory().selected=0;p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(AdventurersPack.REQUIEM.get()));h.assertFalse(Requiem.transform(p,1,0,2),"Cannot modify unheld slots");h.assertFalse(Requiem.transform(p,0,1,2),"Stale form request rejected");h.assertFalse(Requiem.transform(p,0,0,-1),"Invalid target rejected");h.assertTrue(Requiem.transform(p,0,0,2),"Held weapon transforms");h.assertFalse(Requiem.transform(p,0,2,4),"Cooldown prevents rapid transforms");h.assertTrue(p.getMainHandItem().is(AdventurersPack.REQUIEM_SHORTBOW.get()),"Exactly selected form remains");h.succeed();}
 @GameTest(template="empty") public static void offhandAndActiveUse(GameTestHelper h){var p=h.makeMockPlayer();p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.APPLE));p.setItemInHand(InteractionHand.OFF_HAND,new ItemStack(AdventurersPack.REQUIEM_RECURVE.get()));p.startUsingItem(InteractionHand.OFF_HAND);h.assertFalse(Requiem.transform(p,40,3,1),"Cannot transform while drawing bow");p.stopUsingItem();h.assertTrue(Requiem.transform(p,40,3,1),"Offhand transformation supported");h.assertTrue(p.getMainHandItem().is(Items.APPLE)&&p.getOffhandItem().is(AdventurersPack.REQUIEM_SPEAR.get()),"Offhand change preserves main hand");h.succeed();}
 @GameTest(template="empty") public static void recipeAndDistinctBows(GameTestHelper h){var a=(RequiemBowItem)Requiem.item(2);var b=(RequiemBowItem)Requiem.item(3);var c=(RequiemBowItem)Requiem.item(4);h.assertTrue(a.charge(12)==1&&b.charge(12)<1&&c.charge(20)<1,"Distinct charge times");h.assertTrue(a.damage<b.damage&&b.damage<c.damage&&a.velocity<c.velocity,"Larger bows shoot harder");var r=h.getLevel().getRecipeManager().byKey(new net.minecraft.resources.ResourceLocation(AdventurersPack.ID,"requiem"));h.assertTrue(r.isPresent()&&r.get().getResultItem(h.getLevel().registryAccess()).is(AdventurersPack.ENDGAME.get()),"Legacy recipe produces unified Endgame");h.succeed();}
 private static net.minecraft.world.entity.player.Player archer(GameTestHelper h,int form){var p=h.makeMockPlayer();p.getAbilities().instabuild=false;p.setPos(h.absolutePos(new net.minecraft.core.BlockPos(1,2,1)).getCenter());p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Requiem.item(form)));p.getInventory().setItem(9,new ItemStack(Items.ARROW,8));p.startUsingItem(InteractionHand.MAIN_HAND);return p;}
 @GameTest(template="empty") public static void realBowShotConsumesOneArrow(GameTestHelper h){var p=archer(h,4);var stack=p.getMainHandItem();var bow=(RequiemBowItem)stack.getItem();var before=h.getLevel().getEntitiesOfClass(AbstractArrow.class,p.getBoundingBox().inflate(3));bow.releaseUsing(stack,h.getLevel(),p,72000-32);var after=h.getLevel().getEntitiesOfClass(AbstractArrow.class,p.getBoundingBox().inflate(3));after.removeAll(before);h.assertTrue(after.size()==1,"One projectile spawned");h.assertTrue(after.get(0).getBaseDamage()==12&&after.get(0).getDeltaMovement().length()>4,"Greatbow shot has configured power");h.assertTrue(stack.getDamageValue()==0&&p.getInventory().getItem(9).getCount()==7,"The bow stays unworn and one arrow is consumed");after.forEach(a->a.discard());h.succeed();}
 @GameTest(template="empty") public static void infinityAndPowerWork(GameTestHelper h){var p=archer(h,2);var stack=p.getMainHandItem();stack.enchant(Enchantments.INFINITY_ARROWS,1);stack.enchant(Enchantments.POWER_ARROWS,3);var before=h.getLevel().getEntitiesOfClass(AbstractArrow.class,p.getBoundingBox().inflate(3));((RequiemBowItem)stack.getItem()).releaseUsing(stack,h.getLevel(),p,71988);var after=h.getLevel().getEntitiesOfClass(AbstractArrow.class,p.getBoundingBox().inflate(3));after.removeAll(before);h.assertTrue(after.size()==3&&after.stream().allMatch(a->a.getBaseDamage()==9.5),"Power affects arrows");h.assertTrue(after.stream().filter(a->a.pickup==AbstractArrow.Pickup.CREATIVE_ONLY).count()==1&&p.getInventory().getItem(9).getCount()==8,"Infinity consumes no ammunition and prevents free pickups");after.forEach(a->a.discard());h.succeed();}
 @GameTest(template="empty") public static void noAmmoOrChargeNoShot(GameTestHelper h){var p=archer(h,3);var stack=p.getMainHandItem();var bow=(RequiemBowItem)stack.getItem();bow.releaseUsing(stack,h.getLevel(),p,72000);h.assertTrue(stack.getDamageValue()==0&&p.getInventory().getItem(9).getCount()==8,"No charge does not consume items");p.getInventory().setItem(9,ItemStack.EMPTY);bow.releaseUsing(stack,h.getLevel(),p,71980);h.assertTrue(stack.getDamageValue()==0,"No ammo cannot fire");h.succeed();}
}
